<article class="site-mobile-layout <?= c('case', 'page') ?>" id="top"><div class="<?= c('case', 'layout') ?>"><aside class="<?= c('case', 'sidebar') ?>"><div class="<?= c('case', 'heading') ?>"><nav class="<?= c('case', 'breadcrumbs') ?>" aria-label="Хлебные крошки"><a href="/">Главная</a><span aria-hidden="true">›</span><a href="/projects">Портфолио</a><span aria-hidden="true">›</span><span aria-current="page"><?= h($case['title']) ?></span></nav><h1><?= h($case['title']) ?></h1></div><p class="<?= c('case', 'whatDone') ?>"><?= h($case['whatDone'] ?? $case['summary']) ?></p></aside><div class="<?= c('case', 'content') ?>">
<?php foreach ($case['blocks'] ?? [] as $block): $spacing = $block['spacing']; ?>
<?php if ($block['type'] === 'image'): ?><figure class="<?= c('case', 'block') ?>" data-spacing="<?= h($spacing) ?>"><?php if ($block['caption']): ?><figcaption><?= h($block['caption']) ?></figcaption><?php endif; ?><?php if ($block['image']): image($block['image'], $block['alt'], ['class' => c('case', 'image'), 'sizes' => '(max-width: 960px) 100vw, 65vw']); else: ?><div class="<?= c('case', 'imagePlaceholder') ?>" role="img" aria-label="<?= h($block['alt'] ?: 'Место для изображения') ?>"><span>Изображение будет добавлено</span></div><?php endif; ?></figure>
<?php elseif ($block['type'] === 'gallery'): $images = array_filter($block['images'], fn(array $image): bool => $image['image'] !== ''); if ($images): ?><div class="<?= c('case', 'block') ?> <?= c('case', 'gallery') ?>" data-spacing="<?= h($spacing) ?>"><?php foreach ($images as $item) image($item['image'], $item['alt']); ?></div><?php endif; ?>
<?php elseif ($block['type'] === 'callout'): if ($block['text']): ?><aside class="<?= c('case', 'block') ?> <?= c('case', 'callout') ?>" data-spacing="<?= h($spacing) ?>"><?php image('/assets/figma/case-callout-icon.svg', '', ['width' => 24, 'height' => 24]); ?><p><?= h($block['text']) ?></p></aside><?php endif; ?>
<?php else: ?><section class="<?= c('case', 'block') ?> <?= c('case', 'textBlock') ?>" data-spacing="<?= h($spacing) ?>"><?php if ($block['title']): ?><header><h2><?= h($block['title']) ?></h2><span></span></header><?php endif; ?><?php if ($block['body']): ?><p class="<?= c('case', 'body') ?>"><?= h($block['body']) ?></p><?php endif; ?><?php if ($block['listStyle'] !== 'none' && $block['items']): ?><ol class="<?= c('case', 'list') ?>" data-style="<?= h($block['listStyle']) ?>"><?php foreach ($block['items'] as $index => $item): ?><li><?php if ($block['listStyle'] === 'bullet'): image('/assets/figma/case-list-marker.svg', '', ['width' => 8, 'height' => 18]); elseif ($block['listStyle'] === 'numbered'): ?><span class="<?= c('case', 'number') ?>"><?= str_pad((string)($index + 1), 2, '0', STR_PAD_LEFT) ?></span><?php endif; ?><div><?php if ($item['label']): ?><span class="<?= c('case', 'itemLabel') ?>"><?= h($item['label']) ?></span><?php endif; ?><p><?= h($item['text']) ?></p></div></li><?php endforeach; ?></ol><?php endif; ?></section><?php endif; ?>
<?php endforeach; ?></div></div></article>
